sp_widget.client_script:
api.controller=function($scope) {

    var c = this;


    // =========================
    // DEFAULT SECTION
    // =========================

    c.activeSection = 'dashboard';

    c.selectedAssignment = null;


    // =========================
    // SIDEBAR
    // =========================

    c.selectSection = function(section) {

        c.activeSection = section;

        c.selectedAssignment = null;

    };


    // =========================
    // OPEN ASSIGNMENT
    // =========================

    c.openAssignment = function(assignment) {

        c.selectedAssignment = assignment;

        c.activeSection = 'assignments';

    };


    // =========================
    // CLOSE ASSIGNMENT
    // =========================

    c.closeAssignment = function() {

        c.selectedAssignment = null;

    };


    // =========================
    // OPEN RECENT REQUEST
    // =========================

    c.openRequest = function(request) {

        c.selectedAssignment = request;

        c.activeSection = 'assignments';

    };


    // =========================
    // PRIORITY CLASS
    // =========================

    c.getPriorityClass = function(priority) {

        if (!priority) {

            return 'other';

        }


        priority = priority.toLowerCase();


        if (priority === 'high') {

            return 'high';

        }


        if (priority === 'medium') {

            return 'medium';

        }


        if (priority === 'low') {

            return 'low';

        }


        return 'other';

    };


    // =========================
    // STATUS CLASS
    // =========================

    c.getStatusClass = function(status) {

        if (!status) {

            return 'other';

        }


        status = status.toLowerCase();


        if (status.indexOf('pending') !== -1) {

            return 'pending';

        }


        if (status.indexOf('progress') !== -1) {

            return 'progress';

        }


        if (status.indexOf('resolved') !== -1) {

            return 'resolved';

        }


        if (status.indexOf('closed') !== -1) {

            return 'resolved';

        }


        return 'other';

    };

}

sp_widget.css:
/* =====================================
   MAIN DASHBOARD
===================================== */

.admin-dashboard {

    display: flex;

    min-height: 700px;

    background: #f5f7fb;

    color: #1f2937;

}


/* =====================================
   SIDEBAR
===================================== */

.admin-sidebar {

    width: 230px;

    min-width: 230px;

    background: #172554;

    color: white;

    padding: 25px 15px;

}


.sidebar-title {

    font-size: 21px;

    font-weight: 700;

    padding: 10px 15px 25px;

}


.sidebar-menu {

    display: flex;

    flex-direction: column;

    gap: 8px;

}


.sidebar-menu button {

    width: 100%;

    border: none;

    background: transparent;

    color: #dbeafe;

    text-align: left;

    padding: 13px 15px;

    border-radius: 8px;

    font-size: 15px;

    cursor: pointer;

}


.sidebar-menu button:hover {

    background: #1e3a8a;

    color: white;

}


.sidebar-menu button.active {

    background: #2563eb;

    color: white;

    font-weight: 600;

}


/* =====================================
   MAIN AREA
===================================== */

.admin-main {

    flex: 1;

    padding: 30px;

    overflow-x: auto;

}


.welcome-section {

    margin-bottom: 25px;

}


.welcome-section h1 {

    margin: 0 0 7px;

    font-size: 28px;

    font-weight: 700;

}


.welcome-section p {

    margin: 0;

    color: #6b7280;

}


/* =====================================
   KPI CARDS
===================================== */

.kpi-grid {

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 18px;

    margin-bottom: 25px;

}


.kpi-card {

    background: white;

    border-radius: 12px;

    padding: 20px;

    display: flex;

    align-items: center;

    gap: 15px;

    box-shadow:
        0 2px 8px rgba(0, 0, 0, 0.06);

}


.kpi-icon {

    width: 48px;

    height: 48px;

    border-radius: 10px;

    background: #eff6ff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 23px;

}


.kpi-card h3 {

    margin: 0 0 5px;

    font-size: 13px;

    color: #6b7280;

    font-weight: 500;

}


.kpi-card h2 {

    margin: 0;

    font-size: 25px;

    color: #111827;

}


/* =====================================
   DASHBOARD CARDS
===================================== */

.dashboard-card {

    background: white;

    border-radius: 12px;

    padding: 22px;

    margin-bottom: 25px;

    box-shadow:
        0 2px 8px rgba(0, 0, 0, 0.06);

}


.card-header {

    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 18px;

}


.card-header h2 {

    margin: 0;

    font-size: 19px;

}


/* =====================================
   TABLE
===================================== */

.table-container {

    width: 100%;

    overflow-x: auto;

}


table {

    width: 100%;

    border-collapse: collapse;

}


th {

    background: #f8fafc;

    color: #64748b;

    font-size: 13px;

    font-weight: 600;

    padding: 13px;

    text-align: left;

    white-space: nowrap;

}


td {

    padding: 14px 13px;

    border-top: 1px solid #e5e7eb;

    font-size: 14px;

    white-space: nowrap;

}


tbody tr {

    cursor: pointer;

}


tbody tr:hover {

    background: #f8fafc;

}


.empty-message {

    text-align: center;

    color: #9ca3af;

    padding: 25px;

}


/* =====================================
   STATUS BADGES
===================================== */

.status-badge,
.priority-badge {

    display: inline-block;

    padding: 5px 10px;

    border-radius: 20px;

    font-size: 12px;

    font-weight: 600;

}


.status-badge.pending {

    background: #fef3c7;

    color: #92400e;

}


.status-badge.progress {

    background: #dbeafe;

    color: #1e40af;

}


.status-badge.resolved {

    background: #dcfce7;

    color: #166534;

}


.status-badge.other {

    background: #f3f4f6;

    color: #4b5563;

}


/* =====================================
   PRIORITY
===================================== */

.priority-badge.high {

    background: #fee2e2;

    color: #991b1b;

}


.priority-badge.medium {

    background: #fef3c7;

    color: #92400e;

}


.priority-badge.low {

    background: #dcfce7;

    color: #166534;

}


.priority-badge.other {

    background: #f3f4f6;

    color: #4b5563;

}


/* =====================================
   QUICK ACTIONS
===================================== */

.quick-actions {

    display: flex;

    gap: 15px;

    flex-wrap: wrap;

}


.quick-actions button {

    border: none;

    background: #eff6ff;

    color: #1d4ed8;

    padding: 12px 18px;

    border-radius: 8px;

    cursor: pointer;

    font-size: 14px;

    font-weight: 600;

}


.quick-actions button:hover {

    background: #dbeafe;

}


/* =====================================
   ASSIGNMENT DETAILS
===================================== */

.back-button {

    border: none;

    background: #eff6ff;

    color: #1d4ed8;

    padding: 8px 14px;

    border-radius: 7px;

    cursor: pointer;

}


.details-grid {

    display: grid;

    grid-template-columns: repeat(2, 1fr);

    gap: 20px;

}


.details-grid label {

    display: block;

    font-size: 12px;

    color: #6b7280;

    margin-bottom: 5px;

}


.details-grid p {

    margin: 0;

    font-size: 15px;

    font-weight: 500;

}


.description-box {

    grid-column: 1 / -1;

    background: #f8fafc;

    padding: 15px;

    border-radius: 8px;

}


/* =====================================
   REPORT COUNT CARDS
===================================== */

.report-count-grid {

    display: grid;

    grid-template-columns: repeat(4, 1fr);

    gap: 15px;

}


.report-count-card {

    background: #f8fafc;

    border-radius: 10px;

    padding: 18px;

    text-align: center;

}


.report-count-card h3 {

    margin: 0 0 8px;

    font-size: 13px;

    color: #64748b;

}


.report-count-card h2 {

    margin: 0;

    font-size: 26px;

}


/* =====================================
   REPORT LIST
===================================== */

.report-list {

    display: flex;

    flex-direction: column;

}


.report-row {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 14px 5px;

    border-bottom: 1px solid #e5e7eb;

    font-size: 14px;

}


.report-row:last-child {

    border-bottom: none;

}


.report-row strong {

    background: #eff6ff;

    color: #1d4ed8;

    padding: 5px 12px;

    border-radius: 15px;

}


/* =====================================
   SPECIAL REPORT CARDS
===================================== */

.reports-grid {

    display: grid;

    grid-template-columns: repeat(3, 1fr);

    gap: 20px;

}


.report-card {

    background: white;

    border-radius: 12px;

    padding: 25px;

    min-height: 160px;

    box-shadow:
        0 2px 8px rgba(0, 0, 0, 0.06);

}


.report-card:hover {

    box-shadow:
        0 4px 14px rgba(0, 0, 0, 0.10);

}


.report-icon {

    font-size: 30px;

    margin-bottom: 12px;

}


.report-card h2 {

    font-size: 17px;

    margin: 0 0 8px;

}


.report-card p {

    margin: 0;

    color: #6b7280;

    font-size: 13px;

    line-height: 1.5;

}


/* =====================================
   RESPONSIVE
===================================== */

@media (max-width: 1000px) {

    .kpi-grid {

        grid-template-columns: repeat(2, 1fr);

    }


    .reports-grid {

        grid-template-columns: repeat(2, 1fr);

    }

}


@media (max-width: 800px) {

    .report-count-grid {

        grid-template-columns: repeat(2, 1fr);

    }

}


@media (max-width: 700px) {

    .admin-dashboard {

        flex-direction: column;

    }


    .admin-sidebar {

        width: 100%;

        min-width: 100%;

    }


    .sidebar-menu {

        flex-direction: row;

        overflow-x: auto;

    }


    .sidebar-menu button {

        white-space: nowrap;

    }


    .admin-main {

        padding: 20px;

    }


    .kpi-grid {

        grid-template-columns: 1fr;

    }


    .reports-grid {

        grid-template-columns: 1fr;

    }


    .details-grid {

        grid-template-columns: 1fr;

    }


    .description-box {

        grid-column: auto;

    }

}


@media (max-width: 500px) {

    .report-count-grid {

        grid-template-columns: 1fr;

    }

}

sp_widget.script:
(function() {


    // =========================
    // DASHBOARD DATA
    // =========================

    data.totalRequests = 0;
    data.pending = 0;
    data.inProgress = 0;
    data.closed = 0;

    data.recentRequests = [];


    // =========================
    // ASSIGNMENT DATA
    // =========================

    data.totalAssigned = 0;
    data.assignmentPending = 0;
    data.assignmentProgress = 0;
    data.assignmentResolved = 0;

    data.assignments = [];


    // =========================
    // REPORT DATA
    // =========================

    data.problemReports = [];
    data.messHallReports = [];
    data.mealReports = [];

    data.foodQualityCount = 0;
    data.foodWastageCount = 0;
    data.hygieneCount = 0;


    // =========================
    // FOOD COMPLAINT TABLE
    // =========================

    var complaintGR = new GlideRecord(
        'x_snc_campus_foo_1_food_complaint'
    );

    complaintGR.orderByDesc('sys_created_on');

    complaintGR.query();


    while (complaintGR.next()) {


        // =========================
        // TOTAL REQUESTS
        // =========================

        data.totalRequests++;


        // =========================
        // STATE
        // =========================

        var state =
            complaintGR.getDisplayValue('state');


        if (!state) {

            state = 'Pending';

        }


        var stateLower =
            state.toLowerCase();


        // =========================
        // STATUS COUNTS
        // =========================

        if (
            stateLower.indexOf('pending') !== -1
        ) {

            data.pending++;

        }


        else if (
            stateLower.indexOf('progress') !== -1
        ) {

            data.inProgress++;

        }


        else if (
            stateLower.indexOf('closed') !== -1
        ) {

            data.closed++;

        }


        // =========================
        // REPORT VALUES
        // =========================

        var problemType =
            complaintGR.getDisplayValue(
                'problem_type'
            );


        var messHall =
            complaintGR.getDisplayValue(
                'mess_hall'
            );


        var mealType =
            complaintGR.getDisplayValue(
                'meal_type'
            );


        // =========================
        // PROBLEM TYPE REPORT
        // =========================

        if (problemType) {

            var foundProblem = false;


            for (
                var p = 0;
                p < data.problemReports.length;
                p++
            ) {

                if (
                    data.problemReports[p].name ==
                    problemType
                ) {

                    data.problemReports[p].count++;

                    foundProblem = true;

                    break;

                }

            }


            if (!foundProblem) {

                data.problemReports.push({

                    name: problemType,

                    count: 1

                });

            }

        }


        // =========================
        // MESS HALL REPORT
        // =========================

        if (messHall) {

            var foundMess = false;


            for (
                var m = 0;
                m < data.messHallReports.length;
                m++
            ) {

                if (
                    data.messHallReports[m].name ==
                    messHall
                ) {

                    data.messHallReports[m].count++;

                    foundMess = true;

                    break;

                }

            }


            if (!foundMess) {

                data.messHallReports.push({

                    name: messHall,

                    count: 1

                });

            }

        }


        // =========================
        // MEAL TYPE REPORT
        // =========================

        if (mealType) {

            var foundMeal = false;


            for (
                var l = 0;
                l < data.mealReports.length;
                l++
            ) {

                if (
                    data.mealReports[l].name ==
                    mealType
                ) {

                    data.mealReports[l].count++;

                    foundMeal = true;

                    break;

                }

            }


            if (!foundMeal) {

                data.mealReports.push({

                    name: mealType,

                    count: 1

                });

            }

        }


        // =========================
        // USE CASE REPORTS
        // =========================

        var useCase =
            complaintGR.getValue('use_case');


        if (
            useCase ==
            'food_quality_complaint'
        ) {

            data.foodQualityCount++;

        }


        if (
            useCase ==
            'food_wastage_reporting'
        ) {

            data.foodWastageCount++;

        }


        if (
            useCase ==
            'food_hygiene_issue'
        ) {

            data.hygieneCount++;

        }


        // =========================
        // RECENT 5 REQUESTS
        // =========================

        if (
            data.recentRequests.length < 5
        ) {

            data.recentRequests.push({

                sys_id:
                    complaintGR.getUniqueValue(),

                number:
                    complaintGR.getDisplayValue(
                        'number'
                    ),

                student:
                    complaintGR.getDisplayValue(
                        'student'
                    ),

                problem_type:
                    complaintGR.getDisplayValue(
                        'problem_type'
                    ),

                mess_hall:
                    complaintGR.getDisplayValue(
                        'mess_hall'
                    ),

                meal_type:
                    complaintGR.getDisplayValue(
                        'meal_type'
                    ),

                priority:
                    complaintGR.getDisplayValue(
                        'priority'
                    ),

                state:
                    state,

                description:
                    complaintGR.getDisplayValue(
                        'description'
                    )

            });

        }

    }


    // ==================================================
    // MY ASSIGNMENTS
    // ==================================================

    var messStaffGroup =
        new GlideRecord('sys_user_group');


    messStaffGroup.addQuery(
        'name',
        'Mess Staff'
    );


    messStaffGroup.query();


    if (messStaffGroup.next()) {


        // =========================
        // ACTIVE ASSIGNMENTS
        // =========================

        var assignmentGR =
            new GlideRecord(
                'x_snc_campus_foo_1_food_complaint'
            );


        assignmentGR.addQuery(
            'assignment_group',
            messStaffGroup.getUniqueValue()
        );


        assignmentGR.addQuery(
            'state',
            '!=',
            'Closed'
        );


        assignmentGR.orderByDesc(
            'sys_created_on'
        );


        assignmentGR.query();


        while (assignmentGR.next()) {


            var assignmentState =
                assignmentGR.getDisplayValue(
                    'state'
                );


            if (!assignmentState) {

                assignmentState = 'Pending';

            }


            var assignment = {

                sys_id:
                    assignmentGR.getUniqueValue(),

                number:
                    assignmentGR.getDisplayValue(
                        'number'
                    ),

                student:
                    assignmentGR.getDisplayValue(
                        'student'
                    ),

                problem_type:
                    assignmentGR.getDisplayValue(
                        'problem_type'
                    ),

                mess_hall:
                    assignmentGR.getDisplayValue(
                        'mess_hall'
                    ),

                meal_type:
                    assignmentGR.getDisplayValue(
                        'meal_type'
                    ),

                priority:
                    assignmentGR.getDisplayValue(
                        'priority'
                    ),

                state:
                    assignmentState,

                description:
                    assignmentGR.getDisplayValue(
                        'description'
                    )

            };


            data.assignments.push(
                assignment
            );


            data.totalAssigned++;


            var assignmentStateLower =
                assignmentState.toLowerCase();


            if (
                assignmentStateLower.indexOf(
                    'pending'
                ) !== -1
            ) {

                data.assignmentPending++;

            }


            else if (
                assignmentStateLower.indexOf(
                    'progress'
                ) !== -1
            ) {

                data.assignmentProgress++;

            }

        }


        // =========================
        // CLOSED ASSIGNMENTS
        // =========================

        var resolvedGR =
            new GlideRecord(
                'x_snc_campus_foo_1_food_complaint'
            );


        resolvedGR.addQuery(
            'assignment_group',
            messStaffGroup.getUniqueValue()
        );


        resolvedGR.addQuery(
            'state',
            'Closed'
        );


        resolvedGR.query();


        while (resolvedGR.next()) {

            data.assignmentResolved++;

        }

    }


})();
